'use strict';
const paths = {
  plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',close:'m6 6 12 12M6 18 18 6',
  search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',filter:'M4 5h16l-6 7v7l-4-2v-5z',
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
  user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',
  lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4',
  info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  alert:'m12 3 10 18H2zM12 9v5M12 17h.01',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  camera:'M8 5l2-3h4l2 3h5v16H3V5zM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  qr:'M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h3v3h3v3h-6z',
  sync:'M20 7a9 9 0 0 0-15-2L2 8m0-5v5h5M4 17a9 9 0 0 0 15 2l3-3m0 5v-5h-5',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 10h18c0-3-3-3-3-10M9 21h6',
  fuel:'M3 3h10v18H3zM3 10h10M13 8h3v9a2 2 0 0 0 4 0V8l-3-3',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  more:'M5 12h.01M12 12h.01M19 12h.01',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
  shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6',
  route:'M5 4v16h14M9 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0M22 20a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  mail:'M2 4h20v16H2zM2 4l10 8L22 4',edit:'m4 16 12-12 4 4L8 20H4zM14 6l4 4'
};
const icon = name => '<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="' + (paths[name] || paths.file) + '"/></svg>';
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button = (label,cls='',attrs='',ico='') => '<button '+(/\btype=/.test(attrs)?'':'type="button" ')+'class="btn '+cls+'" '+attrs+'>'+ (ico?icon(ico):'')+label+'</button>';
const badge = (label,tone='neutral',ico='') => '<span class="badge '+tone+'">'+(ico?icon(ico):'')+label+'</span>';
const alertBox = (title,body,tone='info',ico='info') => '<div class="alert '+tone+'">'+icon(ico)+'<div><strong>'+title+'</strong><p>'+body+'</p></div></div>';
const field = (id,label,input,help='') => '<div class="field"><label for="'+id+'">'+label+'</label>'+input+(help?'<small id="'+id+'-help">'+help+'</small>':'')+'</div>';
const input = (id,type='text',attrs='') => '<input id="'+id+'" type="'+type+'" '+attrs+'>';
const example = (id,title,body,rule,wide=false) => '<article class="example'+(wide?' wide':'')+'" id="'+id+'"><header class="example-head"><h3>'+title+'</h3><a href="#'+id+'" class="anchor" aria-label="Enlace a '+title+'">#</a></header><div class="example-body">'+body+'</div><div class="rule"><strong>Criterio.</strong> '+rule+'</div></article>';
const sections = [];
const add = (id,title,description,items) => sections.push({id,title,description,items});
const logo = '<span class="logo-plate"><img src="../brand/cee-enriquez-rgb.png" alt="CEE Enriquez" width="98" height="63"></span>';
const map = (id='map') => '<div class="map-demo" id="'+id+'"><svg viewBox="0 0 600 240" role="img" aria-label="Esquema de recorrido de demostración con tres puntos"><path class="plot" d="M10 20h140v60H10zM205 20h160v60H205zM415 15h160v70H415zM20 155h120v60H20zM200 145h160v65H200zM410 145h170v80H410z"/><path class="road" d="M-10 115h630M170 0v250M385 0v250"/><path class="route" d="M75 115h310v70h100"/><circle class="pin" cx="75" cy="115" r="15"/><circle class="pin" cx="270" cy="115" r="15"/><circle class="pin" cx="485" cy="185" r="15"/><text x="71" y="119">1</text><text x="266" y="119">2</text><text x="481" y="189">3</text></svg><span class="map-caption">Esquema ilustrativo · sin ubicación real</span><div class="map-controls">'+button('Capas','outline sm','data-map-layers="'+id+'"')+'</div></div>';
const phone = (title,sub,body,actions='',bottom=true) => '<div class="phone"><div class="phone-status"><strong>09:41</strong><span>Android · demo</span></div><div class="phone-head">'+icon('back')+'<div><h4>'+title+'</h4><small>'+sub+'</small></div></div><div class="phone-body">'+body+'</div>'+(actions?'<div class="phone-actions">'+actions+'</div>':'')+(bottom?'<div class="phone-bottom" aria-label="Navegación móvil de demostración">'+[['grid','Inicio'],['file','Actividad'],['user','Cuenta']].map((x,i)=>'<button type="button" data-bottom-tab aria-pressed="'+(i===0)+'">'+icon(x[0])+x[1]+'</button>').join('')+'</div>':'')+'</div>';
const attachment = name => '<div class="attachment">'+icon('file')+'<div><strong>'+name+'</strong><small>Archivo de demostración · listo</small></div>'+button('','subtle icon','data-dialog="viewer" aria-label="Ver '+name+'"','eye')+'</div>';
const mockSave = 'data-notice="Ejemplo completado. No se envió información."';

add('identidad','Identidad y fundamentos','La marca ordena la interfaz. Los elementos de trabajo acompañan, sin competir por atención.',[
  example('marca','01.01 · Firma de marca','<div class="cols"><div class="brand-board"><img src="../brand/cee-enriquez-rgb.png" alt="Marca completa RGB"></div><div class="brand-board dark-board">'+logo+'</div></div><p class="small muted push">Área libre propuesta: ¼ de la altura del logo. Tamaño mínimo web propuesto: 80 px de ancho.</p>','Usar el archivo original. Conservar proporciones y trazados. En fondo oscuro usar una placa blanca; no invertir ni redibujar el logo.',true),
  example('paleta','01.02 · Paleta institucional','<div class="swatches">'+[['Grafito CEE','#211C18'],['Gris CEE','#5D6166'],['Blanco','#FFFFFF'],['Superficie','#F5F5F4'],['División','#DEDEDC']].map(x=>'<div><div class="swatch" style="background:'+x[1]+'"></div><strong>'+x[0]+'</strong><code>'+x[1]+'</code></div>').join('')+'</div>','La paleta institucional es neutral. El tema oscuro adapta superficies y contraste, sin recolorear la marca.',true),
  example('semantica','01.03 · Color con significado','<div class="stack">'+alertBox('Operación registrada','El movimiento se guardó correctamente.','success','check')+alertBox('Validación pendiente','La operación necesita revisión.','warning','clock')+alertBox('No se pudo sincronizar','El registro continúa guardado en este dispositivo.','danger-tone','alert')+alertBox('Información disponible','Revisá el detalle antes de continuar.')+'</div>','Color, icono y texto juntos. Verde para éxito, ámbar para atención, rojo para error y azul grisáceo para información.'),
  example('tipografia','01.04 · Mark Pro','<div class="type-line"><span style="font-size:30px;font-weight:700">Operación diaria</span><code>700 / 30 px</code></div><div class="type-line"><span style="font-size:22px;font-weight:500">Información del equipo</span><code>500 / 22 px</code></div><div class="type-line"><span>Texto de lectura y descripciones.</span><code>400 / 16 px</code></div><div class="type-line"><span style="font-size:14px;font-weight:500">Etiqueta de formulario</span><code>500 / 14 px</code></div><div class="type-line"><span class="small muted">Actualizado hace 8 minutos</span><code>400 / 12 px</code></div>','Usar únicamente los pesos reales 400, 500 y 700. Cuerpo 16 px y altura de línea 1,5. No simular pesos 600/800.'),
  example('texto','01.05 · Cuerpo, enlaces y listas','<div class="stack"><h4>Antes de registrar un despacho</h4><p class="small">Verificá el equipo y el volumen ingresado. Los movimientos pendientes se conservan en el dispositivo.</p><ul class="small"><li>Identificar el equipo.</li><li>Ingresar el volumen y adjuntar la evidencia.</li><li>Confirmar el registro.</li></ul><p class="small"><a href="#offline">Consultar los estados de sincronización</a></p><blockquote class="notice neutral">Guardado en este dispositivo. Se enviará cuando vuelva la conexión.</blockquote></div>','Español claro, verbos concretos y mensajes que expliquen el próximo paso. Enlaces subrayados; no depender solo del color.'),
  example('geometria','01.06 · Espaciado, bordes y elevación','<div class="stack">'+[4,8,12,16,24,32].map(n=>'<div class="scale-row"><code>'+n+' px</code><div class="spacing-bar" style="width:'+n*4+'px"></div></div>').join('')+'<div class="row"><div class="radius-sample" style="border-radius:6px">Control / 6</div><div class="radius-sample" style="border-radius:8px">Panel / 8</div></div></div>','Múltiplos de 4. Bordes de 1 px; sombras reservadas para menús, modales y otros elementos superpuestos.'),
  example('iconografia','01.07 · Iconografía','<div class="row" style="gap:20px">'+['grid','file','user','pin','fuel','shield','camera','qr','sync','bell','filter','download'].map(icon).join('')+'</div>','Trazo consistente de aproximadamente 1,7–2 px, tamaños 16/20/24. En las webs reutilizar Lucide y en Expo los iconos existentes; mantener el significado y el peso visual.'),
  example('numeros','01.08 · Datos y cifras','<div class="stack"><div class="operational-range">1.248,50 <span class="small muted">litros</span></div><div class="row between small"><span>Fecha de operación</span><strong>07/09/2026 · 09:41</strong></div><div class="row between small"><span>Identificador</span><code>EQ-047 · MOV-2086</code></div></div>','Números alineados a la derecha en tablas. Formato es-AR y unidades explícitas. Horarios operativos en America/Argentina/Buenos_Aires.')
]);
add('navegacion','Estructura y navegación','Una jerarquía estable para saber dónde estás y qué podés hacer.',[
  example('navbar','02.01 · Navbar','<nav class="demo-nav" aria-label="Ejemplo navbar"><strong>CEE / Operaciones</strong><a class="selected" aria-current="page" href="#navbar">Resumen</a><a href="#tabla">Movimientos</a><a href="#permisos">Administración</a>'+button('Mi cuenta','subtle sm','data-dialog="account"','user')+'</nav>','Altura contenida, título del producto y navegación clara. Una selección activa por nivel.',true),
  example('sidebar-demo','02.02 · Sidebar','<nav class="mini-side" aria-label="Ejemplo sidebar"><span class="label">OPERACIÓN</span><a href="#sidebar-demo" class="selected" aria-current="page">'+icon('grid')+'Resumen</a><a href="#tabla">'+icon('fuel')+'Combustible</a><a href="#mapas">'+icon('route')+'Recorridas</a><span class="label push">ADMINISTRACIÓN</span><a href="#permisos">'+icon('user')+'Personas y permisos</a></nav>','Agrupar por tarea, sin una tarjeta por icono. Mantener el indicador de desplazamiento cuando el menú excede la altura.'),
  example('encabezado','02.03 · Encabezado de página','<div class="demo-header"><div><nav class="breadcrumb" aria-label="Ruta de ejemplo"><a href="#navegacion">Operaciones</a><span>/</span><span aria-current="page">Combustible</span></nav><h3>Movimientos</h3><p class="small muted">Consultá los despachos por equipo y obra.</p></div>'+button('Nuevo movimiento','','data-dialog="form"','plus')+'</div>','Título 28–32 px. Descripción breve y una acción principal. Las acciones pasan debajo del título en pantallas chicas.',true),
  example('pestanas','02.04 · Pestañas','<div class="tab-demo"><div class="tabs" role="tablist" aria-label="Detalle del equipo">'+['Resumen','Movimientos','Evidencias'].map((s,i)=>'<button class="tab" role="tab" id="tab-'+i+'" aria-controls="panel-'+i+'" aria-selected="'+(i===0)+'" tabindex="'+(i===0?0:-1)+'">'+s+'</button>').join('')+'</div>'+['Equipo EQ-047 · Excavadora · Centro de costo Obras Norte.','Último despacho: 184,50 L. Consultá los movimientos del equipo.','Dos evidencias disponibles para revisión.'].map((s,i)=>'<div role="tabpanel" class="tab-content" id="panel-'+i+'" aria-labelledby="tab-'+i+'" tabindex="0" '+(i?'hidden':'')+'>'+s+'</div>').join('')+'</div>','Usar flechas izquierda/derecha para recorrer pestañas. Una sola región visible; no confundir navegación con botones de acción.'),
  example('acciones','02.05 · Barra de acciones','<p class="small muted">Los cambios se aplicarán al guardar el formulario.</p><div class="actionbar push">'+button('Cancelar','outline','data-notice="Edición cancelada en la demostración."')+button('Guardar cambios','',mockSave)+'</div>','Acción principal a la derecha en escritorio. En móvil, ancho suficiente y margen inferior seguro. Cancelar conserva una jerarquía secundaria.'),
  example('menu-movil','02.06 · Menú móvil y navegación inferior',phone('Inicio','Operación de campo','<p class="small muted">Una tarea principal por pantalla.</p>'+button('Abrir menú','outline','data-dialog="navigation"','grid'),'',true),'Navegación inferior con 3–5 destinos. Etiquetas siempre visibles. El menú lateral abre como diálogo con foco contenido.')
]);
add('botones','Botones y acciones','El peso visual comunica prioridad; la posición se mantiene predecible.',[
  example('variantes-boton','03.01 · Variantes','<div class="row">'+button('Guardar')+button('Exportar','secondary',mockSave,'download')+button('Cancelar','outline',mockSave)+button('Ver detalle','subtle','data-dialog="detail"')+button('Consultar guía','link','data-dialog="help"')+button('Eliminar','danger','data-dialog="confirm"','trash')+'</div>','Un botón principal por bloque de decisión. El rojo se reserva para acciones destructivas, no para llamar la atención.',true),
  example('tamanos-boton','03.02 · Tamaños e iconos','<div class="row">'+button('Compacto','sm',mockSave)+button('Estándar','',mockSave)+button('Acción amplia','lg',mockSave)+button('Agregar','outline',mockSave,'plus')+button('','outline icon','aria-label="Buscar equipos" data-dialog="search"','search')+'</div>','32 px en acciones compactas de escritorio, 36–44 px en controles generales y 48 dp como mínimo táctil nativo. Botones solo icono requieren nombre accesible.'),
  example('estados-boton','03.03 · Estados de interacción','<div class="row" style="gap:18px">'+[['Normal',''],['Hover','demo-hover'],['Foco','demo-focus'],['Presionado','demo-pressed'],['Deshabilitado','']].map(x=>'<div class="button-state">'+button('Guardar',x[1],x[0]==='Deshabilitado'?'disabled':mockSave)+'<small>'+x[0]+'</small></div>').join('')+'<div class="button-state">'+button('Guardando…','','disabled aria-busy="true"')+'<small>En proceso</small></div></div>','Los estados forzados permiten comparar la propuesta. La carga explica qué ocurre y evita envíos duplicados.',true),
  example('grupo-boton','03.04 · Grupo y selección exclusiva','<div class="row" aria-label="Vista de resultados">'+button('Lista','','data-view-choice aria-pressed="true"','file')+button('Mapa','outline','data-view-choice aria-pressed="false"','pin')+'</div><p class="small muted push" id="view-description">Vista de lista seleccionada.</p>','Para cambiar una vista usar selección persistente. No reutilizar el estado de un botón presionado como confirmación de éxito.')
]);
add('formularios','Formularios y selección','Etiquetas visibles, datos legibles y errores junto al campo que necesita atención.',[
  example('campos','04.01 · Texto, contraseña y búsqueda','<div class="stack">'+field('f-name','Nombre del equipo',input('f-name','text','placeholder="Ej. Excavadora EQ-047" autocomplete="off"'))+field('f-password','Contraseña','<div class="input-group">'+input('f-password','password','value="ejemplo-local" autocomplete="off"')+button('','subtle icon','data-password="f-password" aria-label="Mostrar contraseña" aria-pressed="false"','eye')+'</div>')+field('f-search','Buscar',input('f-search','search','placeholder="Equipo, obra o referencia"'))+'</div>','Etiqueta sobre el control. No usar el placeholder como único nombre. En pantallas táctiles, texto de entrada de 16 px.'),
  example('numericos','04.02 · Números, unidades y PIN','<div class="stack">'+field('f-liters','Volumen','<div class="input-group">'+input('f-liters','number','value="184.50" step="0.01" min="0" inputmode="decimal"')+'<span>L</span></div>')+field('f-counter','Lectura de horómetro','<div class="input-group">'+input('f-counter','number','value="3428" min="0" step="0.1"')+'<span>h</span></div>')+field('f-pin','PIN operativo',input('f-pin','password','inputmode="numeric" maxlength="4" pattern="[0-9]{4}" placeholder="4 dígitos" aria-describedby="f-pin-help"'),'No mostrar ni conservar el PIN después de validar.')+'</div>','La unidad queda fuera del valor. Validación explícita y teclado adecuado; el aspecto del catálogo no cambia reglas de negocio.'),
  example('textarea','04.03 · Texto extenso y ayuda',field('f-notes','Observaciones','<textarea id="f-notes" maxlength="500" placeholder="Describí lo ocurrido…" aria-describedby="f-notes-help"></textarea>','Hasta 500 caracteres. No incluir datos sensibles innecesarios.'),'Altura inicial cómoda, crecimiento vertical y contador cuando exista un límite relevante.'),
  example('selectores','04.04 · Select y selector con búsqueda','<div class="stack">'+field('f-select','Centro de costo','<select id="f-select"><option>Obras Norte</option><option>Taller central</option><option>Planta de áridos</option></select>')+field('f-combo','Equipo (búsqueda local)',input('f-combo','search','placeholder="Escribí EQ o el tipo de equipo" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="combo-options"'))+'<ul class="suggestions" id="combo-options" role="listbox" aria-label="Equipos disponibles" hidden></ul><small class="muted" id="combo-result" role="status">Sin equipo seleccionado.</small></div>','Usar select nativo para listas cortas. Búsqueda cuando la cantidad de opciones lo justifica; mostrar también cero resultados y selección actual.'),
  example('seleccion','04.05 · Checkbox, radio y switch','<div class="stack"><fieldset><legend>Columnas visibles</legend><div class="row"><label class="check"><input type="checkbox" checked>Equipo</label><label class="check"><input type="checkbox" checked>Volumen</label><label class="check"><input type="checkbox">Operador</label></div></fieldset><fieldset><legend>Período</legend><div class="row"><label class="check"><input type="radio" name="period" checked>Hoy</label><label class="check"><input type="radio" name="period">Esta semana</label></div></fieldset><label class="check"><input class="switch" type="checkbox" role="switch" checked>Mostrar equipos activos</label></div>','Checkbox para múltiples opciones, radio para una sola y switch para activar una preferencia. Toda la etiqueta es pulsable.'),
  example('multiseleccion','04.06 · Selección múltiple','<fieldset><legend>Destinatarios de la alerta</legend><div class="stack compact">'+['Guardia Norte','Guardia Planta','Guardia Taller'].map((s,i)=>'<label class="check"><input type="checkbox" data-recipient '+(i===0?'checked':'')+'>'+s+'</label>').join('')+'</div></fieldset><p class="small muted push" id="recipient-count" role="status">1 destinatario seleccionado.</p>','Mostrar cantidad y selección actual. Mantener las opciones elegidas al buscar o cambiar de página.'),
  example('fechas','04.07 · Fecha, hora y rango','<div class="stack"><div class="cols">'+field('f-date','Fecha',input('f-date','date','value="2026-09-07"'))+field('f-time','Hora',input('f-time','time','value="09:41"'))+'</div><div class="cols">'+field('f-from','Desde',input('f-from','date','value="2026-09-01"'))+field('f-to','Hasta',input('f-to','date','value="2026-09-07"'))+'</div>'+field('f-range','Umbral de visualización','<input id="f-range" type="range" min="0" max="100" value="65" aria-describedby="f-range-help"><output id="range-output" for="f-range">65 %</output>','Ejemplo de ajuste visual, sin efecto sobre alertas reales.')+'</div>','Fecha operativa local. Rangos con inicio y fin etiquetados; no hacer depender la precisión de un slider sin valor visible.'),
  example('calendario','04.08 · Calendario desplegable','<div class="row between"><strong class="small">Septiembre 2026</strong><span class="small muted" id="calendar-value" role="status">Día 7 seleccionado</span></div><div class="calendar push">'+['L','M','M','J','V','S','D'].map(s=>'<span aria-hidden="true">'+s+'</span>').join('')+'<span></span>'+Array.from({length:30},(_,i)=>'<button type="button" aria-label="'+(i+1)+' de septiembre de 2026" aria-pressed="'+(i===6)+'" data-day="'+(i+1)+'">'+(i+1)+'</button>').join('')+'</div>','Ejemplo de estados del calendario. En productos, reutilizar el calendario existente y sus reglas de accesibilidad; fechas nativas cuando sean suficientes.'),
  example('validacion','04.09 · Validación y estados de campo','<form id="validation-form" class="stack" novalidate>'+field('f-required','Referencia obligatoria',input('f-required','text','required aria-describedby="validation-message" placeholder="Ingresá una referencia"'))+'<small id="validation-message" role="status" class="muted">La referencia permite identificar el registro.</small>'+field('f-readonly','Generado por el sistema',input('f-readonly','text','value="MOV-2086" readonly'))+field('f-disabled','Campo no disponible',input('f-disabled','text','value="Sin permiso de edición" disabled'))+button('Probar validación','','type="submit"')+'</form>','Error junto al campo y foco en el primer problema. Solo lectura permite consultar y copiar; deshabilitado comunica indisponibilidad.'),
  example('adjuntos','04.10 · Adjuntar archivos','<label class="upload">'+icon('file')+'<strong>Agregar evidencia</strong><span>Imágenes o PDF · máximo 10 MB por archivo</span><input type="file" id="file-upload" accept="image/*,application/pdf" multiple aria-label="Agregar evidencia de demostración"></label><div id="file-list" class="stack compact push" role="status"></div>','Mostrar tipo, tamaño, progreso y posibilidad de quitar. En este catálogo la selección se procesa únicamente en memoria local.'),
  example('formulario-completo','04.11 · Formulario agrupado','<form class="stack" data-local-form><fieldset><legend>Datos del movimiento</legend><div class="cols">'+field('full-equipment','Equipo','<select id="full-equipment" required><option value="">Seleccionar equipo</option><option>EQ-047 · Excavadora</option><option>EQ-082 · Camión</option></select>')+field('full-volume','Volumen (L)',input('full-volume','number','required min="0.01" step="0.01" placeholder="0,00"'))+'</div></fieldset>'+field('full-note','Observación','<textarea id="full-note" rows="2"></textarea>')+'<div class="actionbar">'+button('Limpiar','outline','type="reset"')+button('Registrar movimiento','','type="submit"')+'</div></form>','Agrupar por significado. Una sola columna en móvil, mensajes de error claros y acción principal al final.',true)
]);
