add('datos','Datos y seguimiento','La información operativa debe poder leerse, compararse y revisarse con rapidez.',[
  example('tabla','05.01 · Tabla operativa interactiva','<div class="table-toolbar">'+field('table-search','Buscar movimientos',input('table-search','search','placeholder="Referencia, equipo u obra"'))+field('table-status','Estado','<select id="table-status"><option value="">Todos los estados</option><option>Validado</option><option>Pendiente</option><option>Revisión</option></select>')+button('Exportar','outline','id="export-table"','download')+'</div><div class="table-wrap" tabindex="0" role="region" aria-label="Movimientos, tabla con desplazamiento horizontal"><table><thead><tr><th><input id="select-page" type="checkbox" aria-label="Seleccionar filas de esta página"></th><th>REFERENCIA</th><th>EQUIPO / OBRA</th><th><button class="btn subtle sm" id="sort-liters">VOLUMEN ↕</button></th><th>ESTADO</th><th>DETALLE</th></tr></thead><tbody id="table-body"></tbody></table></div><div class="table-foot"><span id="table-count" role="status"></span><div class="row">'+button('Anterior','outline sm','id="page-prev"')+'<span id="page-label"></span>'+button('Siguiente','outline sm','id="page-next"')+'</div></div>','Probar búsqueda, estado, ordenamiento, selección, paginación y detalle expandible. La exportación descarga únicamente los registros ficticios filtrados.',true),
  example('indicadores','05.02 · Indicadores',metrics,'Cifras con unidad, período y contexto. Evitar tarjetas decorativas y porcentajes sin referencia.',true),
  example('listas','05.03 · Listas y ficha de detalle','<div class="list-item"><div><strong>EQ-047 · Excavadora</strong><small>Obras Norte · Último movimiento 09:32</small></div>'+badge('Activo','success','check')+'</div><div class="list-item"><div><strong>EQ-082 · Camión</strong><small>Planta de áridos · Último movimiento 09:18</small></div>'+button('Ver','outline sm','data-dialog="detail"')+'</div><dl class="small"><div class="row between"><dt>Operación</dt><dd>MOV-2086</dd></div><div class="row between"><dt>Volumen</dt><dd>184,50 L</dd></div></dl>','Listas para lectura rápida; fichas con pares etiqueta/valor. Mantener las unidades y estados visibles.'),
  example('graficos','05.04 · Gráfico y leyenda',bars+'<details class="push"><summary>Ver valores del gráfico</summary><div>Lun 128 L · Mar 164 L · Mié 112 L · Jue 185 L · Vie 147 L · Sáb 92 L · Dom 76 L.</div></details>','Una serie neutral por defecto. Más series requieren tonos distinguibles, etiquetas y una alternativa textual accesible.'),
  example('timeline','05.05 · Actividad y trazabilidad','<div class="timeline"><div><strong>Operación registrada</strong><small>09:32 · Dispositivo de demostración</small></div><div><strong>Evidencias sincronizadas</strong><small>09:34 · 2 archivos</small></div><div><strong>Validación completada</strong><small>09:41 · Responsable operativo</small></div></div>','Orden cronológico explícito. Mostrar actor, estado y hora cuando aporten trazabilidad.'),
  example('permisos','05.06 · Roles y permisos','<div class="table-wrap"><table><thead><tr><th>PERFIL</th><th>CONSULTAR</th><th>EDITAR</th><th>ADMINISTRAR</th></tr></thead><tbody><tr><td>Administración</td><td>Sí</td><td>No</td><td>No</td></tr><tr><td>Admin técnico</td><td>Sí</td><td>Sí</td><td>Sí</td></tr></tbody></table></div>'+alertBox('Acceso de consulta','Podés ver y exportar información. Este perfil no permite modificar registros.','info','lock'),'Distinguir administración de admin técnico. El diseño refleja permisos reales; ocultar o deshabilitar una acción no reemplaza el control de acceso.'),
  example('tv','05.07 · Panel de TV','<div class="tv"><div class="tv-head"><div><span class="label">CONTROL OPERATIVO</span><h3 class="push">Combustible · Resumen diario</h3></div>'+badge('Actualizado 09:41','neutral','clock')+'</div>'+metrics+bars+'</div>','Vista de lectura a distancia: cifras mayores, pocas columnas y actualización visible. No depender de hover. Edición de distribución separada de la vista operativa.',true),
  example('config-panel','05.08 · Configuración del panel','<div class="stack"><label class="check"><input type="checkbox" checked>Mostrar consumo diario</label><label class="check"><input type="checkbox" checked>Mostrar equipos atendidos</label>'+field('panel-width','Ancho de la sección','<select id="panel-width"><option>Completo</option><option>Mitad</option></select>')+button('Aplicar distribución','outline',mockSave)+'</div>','Controles de configuración agrupados. En la integración, mantener el arrastre existente con una alternativa de teclado; este ejemplo no simula un editor completo.')
]);
add('superposiciones','Diálogos y ayudas','Interrumpir solo lo necesario, conservando el contexto y el control del usuario.',[
  example('modal','06.01 · Modal de edición','<p class="small muted">Datos acotados, una decisión por diálogo.</p><div class="push">'+button('Editar movimiento','outline','data-dialog="form"','edit')+'</div>','Título, cierre visible, foco inicial y Escape. Contenido desplazable y acciones siempre accesibles.'),
  example('confirmacion','06.02 · Confirmación destructiva','<p class="small muted">La consecuencia aparece antes de confirmar.</p><div class="push">'+button('Eliminar registro','danger','data-dialog="confirm"','trash')+'</div>','Identificar el elemento y la consecuencia. Foco inicial en cancelar para la demostración destructiva.'),
  example('panel-lateral','06.03 · Panel lateral','<p class="small muted">Consultar un registro sin abandonar la lista.</p><div class="push">'+button('Abrir detalle','outline','data-dialog="drawer"','file')+'</div>','Adecuado para detalle secundario. En móvil puede ocupar el ancho disponible. Mantener cierre y retorno del foco.'),
  example('hoja-inferior','06.04 · Hoja inferior móvil','<p class="small muted">Selección corta, al alcance de la mano.</p><div class="push">'+button('Elegir evidencia','outline','data-dialog="sheet"','camera')+'</div>','Respetar áreas seguras. El teclado no debe tapar la acción principal; evitar alturas rígidas.'),
  example('dropdown','06.05 · Dropdown de acciones','<div class="menu-wrap">'+button('Acciones','outline','id="dropdown-trigger" aria-expanded="false" aria-controls="dropdown-menu"','more')+'<div class="popup-menu" id="dropdown-menu" hidden>'+['Ver detalle','Duplicar borrador','Exportar registro'].map(s=>'<button type="button" data-menu-action="'+s+'">'+s+'</button>').join('')+'</div></div>','Menú de acciones secundarias. Cerrar con Escape o al seleccionar. Flechas para recorrer sus acciones.'),
  example('ayudas','06.06 · Tooltip, popover y acordeón','<div class="stack"><span class="tooltip-wrap">'+button('Qué significa','subtle','aria-describedby="tooltip-description"','info')+'<span class="tooltip" role="tooltip" id="tooltip-description">El volumen informado corresponde al total del despacho.</span></span><div>'+button('Ayuda contextual','outline','id="popover-trigger" aria-expanded="false" aria-controls="popover-body"')+'<div class="popover-inline" id="popover-body" hidden>Usá la lectura del medidor como referencia. Si detectás una diferencia, registrá una observación.</div></div><details><summary>Más información sobre el registro</summary><div>La evidencia y la observación acompañan al movimiento en su historial.</div></details></div>','Ayuda breve en tooltip; explicación persistente en popover o acordeón. Nunca esconder información obligatoria en un hover.'),
  example('visor','06.07 · Visor de adjuntos',attachment('Evidencia del equipo.svg'),'Imagen, video o documento con nombre visible, controles accesibles y cierre consistente. No asumir que miniatura disponible equivale a subida completada.'),
  example('toast-demo','06.08 · Confirmación breve',button('Mostrar confirmación','outline','data-notice="Cambios guardados en la demostración."','check'),'Mensajes informativos no bloqueantes con región de estado accesible. Errores que requieren acción permanecen junto al contenido.')
]);
add('estados','Estados del sistema','Cada estado explica qué pasó, qué se conserva y qué podés hacer después.',[
  example('carga','07.01 · Carga y progreso','<div class="stack"><span class="small muted">Cargando movimientos…</span><div class="skeleton" style="width:60%"></div><div class="skeleton"></div><div class="skeleton" style="width:82%"></div><hr class="divider"><label for="loading-progress" class="small">Preparando evidencias · 68 %</label><progress id="loading-progress" max="100" value="68">68 %</progress></div>','Skeleton para contenido por cargar, progreso cuando existe una medición y texto en procesos largos. No inventar porcentajes.'),
  example('vacio','07.02 · Sin registros','<div class="empty">'+icon('file')+'<h4>Todavía no hay movimientos</h4><p>Los despachos registrados aparecerán en esta sección.</p>'+button('Registrar movimiento','outline','data-dialog="form"','plus')+'</div>','Distinguir ausencia de datos de un error. Ofrecer la acción inicial solo si el usuario tiene permiso.'),
  example('sin-resultados','07.03 · Sin coincidencias','<div class="empty">'+icon('search')+'<h4>No encontramos coincidencias</h4><p>Probá con otro equipo o limpiá los filtros.</p>'+button('Limpiar filtros','outline','data-clear-filters')+'</div>','Conservar el contexto y permitir recuperar la lista sin rehacer la búsqueda.'),
  example('error','07.04 · Error recuperable',alertBox('No pudimos cargar el detalle','Reintentá la consulta. Los datos guardados no se modificaron.','danger-tone','alert')+'<div class="row push">'+button('Reintentar','outline','data-retry','sync')+button('Ver diagnóstico','subtle','data-dialog="diagnostic"')+'</div><p class="small muted push" data-retry-status role="status"></p>','Mensaje útil primero. Código de diagnóstico secundario; no mostrar tokens, trazas internas o credenciales.'),
  example('restringido','07.05 · Acceso restringido','<div class="empty">'+icon('lock')+'<h4>Este módulo no está habilitado</h4><p>Solicitá acceso al responsable de tu equipo.</p>'+button('Volver al inicio','outline','data-go="inicio"')+'</div>','Explicar la limitación sin ofrecer acciones que el perfil no puede realizar.'),
  example('sincronizacion','07.06 · Avisos persistentes','<div class="stack">'+alertBox('Sin conexión','Podés continuar con las funciones disponibles en este dispositivo.','warning','info')+alertBox('Actualización disponible','Aplicá la actualización al terminar la operación actual.','info','download')+'</div>','Los avisos persistentes informan restricciones reales. No bloquear una operación local por una consulta remota diferible.')
]);
add('operacion','Operación y dispositivos','Patrones específicos de campo que comparten el mismo lenguaje visual.',[
  example('offline','08.01 · Guardado local y sincronización','<div class="stack"><div id="offline-alert">'+alertBox('Guardado en este dispositivo','Pendiente de sincronización. El registro está conservado localmente.','warning','check')+'</div><div class="row">'+button('Simular sincronización','outline','id="sync-success"','sync')+button('Simular fallo','subtle','id="sync-fail"')+'</div><p class="small muted" id="sync-status" role="status">Estado: pendiente de sincronización.</p></div>','Separar guardado local y envío remoto. Un fallo de red no debe presentarse como pérdida del registro.',true),
  example('gps','08.02 · Ubicación y precisión','<div class="stack"><div id="gps-state">'+alertBox('Ubicación disponible','Precisión aproximada: 18 m. Capturada a las 09:41.','success','pin')+'</div><div class="row">'+button('Precisión baja','outline sm','data-gps="low"')+button('Permiso pendiente','outline sm','data-gps="permission"')+button('Disponible','outline sm','data-gps="ready"')+'</div></div>','Mostrar precisión y estado. Respetar la política del flujo: cuando corresponda, guardar la mejor ubicación con una nota de auditoría.'),
  example('camara-qr','08.03 · Cámara y QR','<div class="camera"><div class="scan-frame">'+icon('qr')+'</div><span>Ubicá el QR del equipo dentro del marco.</span></div><div class="row push">'+button('Simular lectura','outline','data-dialog="qr-result"','qr')+button('Carga manual','subtle','data-dialog="form"')+'</div>','Después de leer, cerrar la cámara antes de mostrar el resultado. Ofrecer alternativa manual cuando el flujo la permita.'),
  example('evidencias','08.04 · Captura, revisión y envío','<div class="stack"><div class="camera">'+icon('camera')+'<span>Vista de revisión de la evidencia</span></div><div class="row">'+button('Repetir','outline','data-notice="Nueva captura simulada."')+button('Aceptar','',mockSave,'check')+'</div>'+attachment('Medidor — demostración.svg')+'<label class="small" for="evidence-progress">Sincronizando adjuntos · 43 %</label><progress id="evidence-progress" max="100" value="43">43 %</progress></div>','Diferenciar capturando, preparando, guardado local, subiendo y completado. Mantener la evidencia local ante un fallo de envío.'),
  example('pin-validacion','08.05 · Validación con PIN','<form class="stack" data-pin-form>'+field('operation-pin','PIN del operador',input('operation-pin','password','inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required autocomplete="off" aria-describedby="operation-pin-help"'),'Ingresá 4 dígitos de demostración.')+button('Validar con PIN','','type="submit"','shield')+'<p class="small muted" role="status" data-pin-status>La validación está pendiente.</p></form>','Campo enmascarado, longitud explícita y borrado al finalizar. El ejemplo no autentica ni consulta operaciones reales.'),
  example('recorridas','08.06 · Recorrida y puntos','<div class="stack"><div class="row between"><strong class="small">Recorrida del predio</strong>'+badge('En curso','info','route')+'</div><label for="route-progress" class="small">2 de 3 puntos registrados</label><progress id="route-progress" max="3" value="2">2 de 3</progress><div class="list-item"><span>01 · Acceso principal</span>'+badge('Registrado','success','check')+'</div><div class="list-item"><span>02 · Depósito</span>'+badge('Registrado','success','check')+'</div><div class="list-item"><span>03 · Taller</span>'+button('Registrar','outline sm','id="route-check"')+'</div><p class="small muted" role="status" id="route-state">Falta 1 punto para completar.</p></div>','Progreso basado en puntos registrados. Estados distinguibles y orden del recorrido explícito.'),
  example('alerta-guardia','08.07 · Alerta al guardia y Hombre vivo','<div class="stack">'+alertBox('Mensaje administrativo','Revisá el acceso norte antes de iniciar la próxima recorrida.','warning','bell')+'<div class="row">'+button('Ver alerta','outline','data-dialog="guard-alert"')+button('Hombre vivo','outline','data-dialog="alive"','shield')+'</div></div>','Conservar confirmación y prioridad de alertas. No competir con actualizaciones ni ocultar un aviso crítico detrás de otro modal.'),
  example('actualizacion','08.08 · Actualización y descarga','<div class="stack"><h4>Actualización disponible</h4><p class="small muted">Nueva versión de demostración. Terminá tu operación antes de reiniciar.</p><div class="row">'+button('Ver actualización','outline','data-dialog="update"','download')+badge('Instalación manual','neutral')+'</div></div>','Distinguir opcional, obligatoria, descarga y lista para instalar. La obligatoriedad y el reinicio dependen del flujo aprobado de cada producto.'),
  example('accesos','08.09 · Control de accesos y check-in','<div class="stack"><div class="row between"><h4>Acceso Norte</h4>'+badge('Turno activo','success','check')+'</div>'+field('visitor-name','Persona o vehículo',input('visitor-name','text','placeholder="Identificador de demostración"'))+'<div class="row">'+button('Registrar ingreso','',mockSave,'plus')+button('Registrar egreso','outline',mockSave)+'</div></div>','Ingreso y egreso tienen etiquetas inequívocas. Conservar hora, estado del turno y trazabilidad del registro.'),
  example('widget','08.10 · Widget y acceso rápido','<div class="widget"><div class="row between"><span class="label">COMBUSTIBLE</span>'+icon('fuel')+'</div><h4>Despacho a equipo</h4><p class="small muted">Acceso directo a una nueva operación.</p><div class="push">'+button('Nuevo despacho','lg','data-go="despacho-movil"','plus')+'</div></div>','Una acción principal, lectura breve y contraste propio. Adaptar tamaños al host de widgets de Android; no depender de estilos CSS.')
]);
add('desplazamiento','Desplazamiento y áreas seguras','El contenido puede crecer sin desplazar las acciones fuera del alcance.',[
  example('scroll','09.01 · Scroll de sección','<div class="scroll-demo" tabindex="0" role="region" aria-label="Lista desplazable de ejemplo"><header>Movimientos recientes · encabezado fijo</header>'+Array.from({length:9},(_,i)=>'<p>MOV-'+(2086-i)+' · Movimiento de demostración</p>').join('')+'</div>','Indicador visible, desplazamiento nativo y encabezado fijo cuando ayude a identificar las filas. No ocultar scrollbars por decoración.'),
  example('scroll-tabla','09.02 · Tabla ancha y encabezado fijo','<div class="scroll-demo" tabindex="0" role="region" aria-label="Tabla ancha, desplazamiento horizontal y vertical"><table><thead><tr><th>REFERENCIA</th><th>EQUIPO</th><th>OBRA</th><th>FECHA / HORA</th><th>OBSERVACIÓN</th></tr></thead><tbody>'+Array.from({length:10},(_,i)=>'<tr><td>MOV-'+(2086-i)+'</td><td>EQ-047</td><td>Obras Norte</td><td>07/09/2026 · 09:41</td><td>Registro con evidencia adjunta para revisión</td></tr>').join('')+'</tbody></table></div>','El desplazamiento horizontal queda en la tabla, no en toda la página. Mantener encabezados y nombres de columna.'),
  example('teclado','09.03 · Teclado y acción visible',phone('Volumen','Ejemplo con teclado numérico','<div class="phone-card">'+field('keyboard-volume','Volumen (L)',input('keyboard-volume','number','value="184.50" inputmode="decimal"'))+'</div>'+button('Guardar en dispositivo','',mockSave,'check')+'<div class="key-board">'+Array.from({length:9},(_,i)=>'<span>'+(i+1)+'</span>').join('')+'<span>,</span><span>0</span><span>←</span><span class="caption">Teclado ilustrativo · no interactivo</span></div>','',false),'En Android usar áreas seguras y ajuste ante teclado. Mantener el botón sobre el teclado o al final de un contenido desplazable; validar en dispositivo real.'),
  example('scroll-modal','09.04 · Modal con contenido largo',button('Abrir contenido extenso','outline','data-dialog="long"'),'Cabecera y acciones fuera del área interna desplazable. El foco nunca queda detrás del diálogo; Escape devuelve el control al disparador.')
]);
