let selectedFiles=[];
function renderFiles(){const list=$('file-list');list.replaceChildren();selectedFiles.forEach((f,i)=>{const row=document.createElement('div');row.className='attachment';const text=document.createElement('span');text.textContent=f.name+' · '+Math.round(f.size/1024)+' KB';const remove=document.createElement('button');remove.type='button';remove.className='btn subtle sm';remove.textContent='Quitar';remove.setAttribute('aria-label','Quitar '+f.name);remove.onclick=()=>{selectedFiles.splice(i,1);renderFiles();};row.append(text,remove);list.append(row);});}
$('file-upload').addEventListener('change',e=>{const files=[...e.target.files];const invalid=files.filter(f=>f.size>10*1024*1024||(!f.type.startsWith('image/')&&f.type!=='application/pdf'));selectedFiles=files.filter(f=>!invalid.includes(f));renderFiles();if(invalid.length){const error=document.createElement('p');error.className='small';error.style.color='var(--danger)';error.textContent='No se agregaron '+invalid.length+' archivos: tipo no admitido o tamaño mayor a 10 MB.';$('file-list').append(error);}e.target.value='';});
