function filteredRecords(){const term=$('table-search').value.toLowerCase();let rows=tableRecords.filter(r=>(r.id+' '+r.equipment+' '+r.site).toLowerCase().includes(term)&&(!$('table-status').value||r.state===$('table-status').value));if(sortDirection)rows.sort((a,b)=>(a.liters-b.liters)*sortDirection);return rows;}
function renderTable(){
 const records=filteredRecords();const pages=Math.max(1,Math.ceil(records.length/3));tablePage=Math.min(tablePage,pages-1);const rows=records.slice(tablePage*3,tablePage*3+3);
 $('table-body').innerHTML=rows.length?rows.map(r=>'<tr><td><input type="checkbox" data-row-select="'+r.id+'" aria-label="Seleccionar '+r.id+'" '+(selectedRows.has(r.id)?'checked':'')+'></td><td><strong>'+r.id+'</strong><br><small class="muted">07/09 · 09:32</small></td><td>'+r.equipment+'<br><small class="muted">'+r.site+'</small></td><td class="numeric">'+r.liters.toLocaleString('es-AR',{minimumFractionDigits:2})+' L</td><td>'+badge(r.state,r.state==='Validado'?'success':'warning',r.state==='Validado'?'check':'clock')+'</td><td>'+button(expandedRows.has(r.id)?'Cerrar':'Ver','subtle sm','data-expand="'+r.id+'" aria-expanded="'+expandedRows.has(r.id)+'" aria-controls="detail-'+r.id+'"')+'</td></tr><tr id="detail-'+r.id+'" class="detail-row" '+(expandedRows.has(r.id)?'':'hidden')+'><td colspan="6">Origen: Cisterna 03 · '+r.site+' · '+r.equipment+'. Evidencia adjunta de demostración. '+button('Abrir ficha','outline sm','data-dialog="detail"')+'</td></tr>').join(''):'<tr><td colspan="6">No hay movimientos para estos filtros.</td></tr>';
 $('table-count').textContent=records.length+' movimientos · '+selectedRows.size+' seleccionados';$('page-label').textContent=(tablePage+1)+' / '+pages;$('page-prev').disabled=tablePage===0;$('page-next').disabled=tablePage===pages-1;
 $('select-page').checked=rows.length>0&&rows.every(r=>selectedRows.has(r.id));$('select-page').indeterminate=rows.some(r=>selectedRows.has(r.id))&&!$('select-page').checked;$('select-page').disabled=!rows.length;
 $('sort-liters').closest('th').setAttribute('aria-sort',sortDirection===1?'ascending':sortDirection===-1?'descending':'none');
}
['table-search','table-status'].forEach(id=>$(id).addEventListener('input',()=>{tablePage=0;renderTable();}));
$('page-prev').addEventListener('click',()=>{tablePage--;renderTable();});$('page-next').addEventListener('click',()=>{tablePage++;renderTable();});
$('sort-liters').addEventListener('click',()=>{sortDirection=sortDirection===1?-1:1;renderTable();});
$('table-body').addEventListener('click',e=>{const b=e.target.closest('[data-expand]');if(b){expandedRows.has(b.dataset.expand)?expandedRows.delete(b.dataset.expand):expandedRows.add(b.dataset.expand);renderTable();document.querySelector('[data-expand="'+b.dataset.expand+'"]')?.focus();}});
$('table-body').addEventListener('change',e=>{if(e.target.dataset.rowSelect){e.target.checked?selectedRows.add(e.target.dataset.rowSelect):selectedRows.delete(e.target.dataset.rowSelect);renderTable();document.querySelector('[data-row-select="'+e.target.dataset.rowSelect+'"]')?.focus();}});
$('select-page').addEventListener('change',e=>{filteredRecords().slice(tablePage*3,tablePage*3+3).forEach(r=>e.target.checked?selectedRows.add(r.id):selectedRows.delete(r.id));renderTable();});
$('export-table').addEventListener('click',()=>{const csv=['Referencia;Equipo;Obra;Litros;Estado',...filteredRecords().map(r=>[r.id,r.equipment,r.site,String(r.liters).replace('.',','),r.state].join(';'))].join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cee-movimientos-demostracion.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Se exportaron los movimientos ficticios filtrados.');});
renderTable();
let syncTimer;
function syncDemo(fail){clearTimeout(syncTimer);$('sync-success').disabled=true;$('sync-fail').disabled=true;$('offline-alert').innerHTML=alertBox('Sincronizando','El registro permanece guardado en el dispositivo.','info','sync');$('sync-status').textContent='Estado: sincronizando.';syncTimer=setTimeout(()=>{$('offline-alert').innerHTML=fail?alertBox('No se pudo sincronizar','El registro sigue guardado en este dispositivo. Podés reintentar.','danger-tone','alert'):alertBox('Sincronizado','La copia remota fue confirmada en esta demostración.','success','check');$('sync-status').textContent=fail?'Estado: fallo de sincronización. Guardado local conservado.':'Estado: sincronizado.';$('sync-success').disabled=false;$('sync-fail').disabled=false;},900);}
$('sync-success').addEventListener('click',()=>syncDemo(false));$('sync-fail').addEventListener('click',()=>syncDemo(true));
document.querySelector('[data-retry]').addEventListener('click',e=>{const b=e.currentTarget;b.disabled=true;document.querySelector('[data-retry-status]').textContent='Reintentando…';setTimeout(()=>{b.disabled=false;document.querySelector('[data-retry-status]').textContent='Consulta de demostración recuperada.';},700);});
document.querySelectorAll('[data-gps]').forEach(b=>b.addEventListener('click',()=>{$('gps-state').innerHTML=b.dataset.gps==='low'?alertBox('Precisión limitada','Mejor coordenada disponible: ±86 m. Agregar nota según la operación.','warning','pin'):b.dataset.gps==='permission'?alertBox('Permiso de ubicación pendiente','Habilitá el permiso para continuar con la ubicación.','warning','pin'):alertBox('Ubicación disponible','Precisión aproximada: 18 m. Capturada a las 09:41.','success','pin');}));
$('route-check').addEventListener('click',e=>{e.currentTarget.disabled=true;e.currentTarget.textContent='Registrado';$('route-progress').value=3;$('route-progress').previousElementSibling.textContent='3 de 3 puntos registrados';$('route-state').textContent='Recorrida completada en la demostración.';});
function renderInventory(){const term=$('inventory-search').value.toLowerCase();const rows=sourceData.sources.filter(r=>(r.project+' '+r.file+' '+r.refs.join(' ')+' '+(r.exclusion||'')).toLowerCase().includes(term));$('inventory-body').innerHTML=rows.map(r=>'<tr><td>'+esc(r.project)+'</td><td>'+esc(r.file)+'</td><td>'+(r.exclusion?esc(r.exclusion):r.refs.map(ref=>'<a href="#'+ref+'">'+ref+'</a>').join(''))+'</td></tr>').join('');$('inventory-summary').textContent=sourceData.sources.length+' archivos de interfaz inventariados · '+rows.length+' visibles. Cada archivo conserva proyecto y referencia relativa.';}
$('inventory-search').addEventListener('input',renderInventory);renderInventory();
if(location.hash)setTimeout(revealHash,50);
